DELIMITER $$
--
-- Procedimientos
--
DROP PROCEDURE IF EXISTS `sp_eliminar_usuario`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_eliminar_usuario` (IN `p_id` INT)  MODIFIES SQL DATA BEGIN
    UPDATE usuario SET estatus = 0 WHERE id = p_id;
END$$

DROP PROCEDURE IF EXISTS `sp_InsertarPoliza`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_InsertarPoliza` (IN `p_nPoliza` VARCHAR(50), IN `p_usuario_id` INT, IN `p_aseguradora_id` INT, IN `p_vehiculo` INT)  MODIFIES SQL DATA BEGIN
    INSERT INTO poliza (num_poliza, aseguradora_id, usuario_id, vehiculo_id)
    VALUES (p_nPoliza, p_aseguradora_id, p_usuario_id, p_vehiculo);
END$$

DROP PROCEDURE IF EXISTS `sp_listar_usuarios`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_listar_usuarios` ()  READS SQL DATA BEGIN
    SELECT id, nombre, apellido_p, email, alias, rol_id FROM usuario;
END$$

DROP PROCEDURE IF EXISTS `sp_registrarSiniestro`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrarSiniestro` (IN `p_fecha` DATE, IN `p_hora` TIME, IN `p_direccion` TEXT, IN `p_descripcion` TEXT, IN `p_poliza_id` INT UNSIGNED, IN `p_usuario_id` INT UNSIGNED)  MODIFIES SQL DATA BEGIN
    DECLARE v_propietario INT UNSIGNED DEFAULT NULL;
    DECLARE v_ajustadores INT DEFAULT 0;

    SELECT MIN(usuario_id) INTO v_propietario
    FROM poliza WHERE id = p_poliza_id;

    IF v_propietario IS NULL OR v_propietario <> p_usuario_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La poliza no pertenece al asegurado.';
    END IF;

    SELECT COUNT(*) INTO v_ajustadores
    FROM usuario u INNER JOIN rol r ON r.id = u.rol_id
    WHERE r.slug = 'ajustador' AND u.estatus = 1;

    IF v_ajustadores = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay ajustadores activos para asignar el reporte.';
    END IF;

    INSERT INTO siniestro (fecha, hora, direccion, descripcion, poliza_id)
    VALUES (p_fecha, p_hora, p_direccion, p_descripcion, p_poliza_id);

    SELECT LAST_INSERT_ID() AS siniestro_id;
END$$

DROP PROCEDURE IF EXISTS `sp_registrar_usuario`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_usuario` (IN `p_nombre` VARCHAR(50), IN `p_apellido_p` VARCHAR(50), IN `p_apellido_m` VARCHAR(50), IN `p_nacimiento` DATE, IN `p_genero` VARCHAR(20), IN `p_email` VARCHAR(100), IN `p_contrasena` VARCHAR(255), IN `p_alias` VARCHAR(50), IN `p_foto_perfil` LONGBLOB)  MODIFIES SQL DATA SQL SECURITY INVOKER BEGIN
    DECLARE v_rol_asegurado TINYINT UNSIGNED DEFAULT NULL;
    SELECT MIN(id) INTO v_rol_asegurado FROM rol WHERE slug = 'asegurado';
    IF v_rol_asegurado IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Falta el rol asegurado.';
    END IF;
    INSERT INTO usuario (
        nombre, apellido_p, apellido_m, nacimiento, genero,
        email, contrasena, alias, foto_perfil, rol_id
    ) VALUES (
        p_nombre, p_apellido_p, p_apellido_m, p_nacimiento, p_genero,
        p_email, p_contrasena, p_alias, p_foto_perfil, v_rol_asegurado
    );
END$$

DROP PROCEDURE IF EXISTS `sp_validar_usuario`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_validar_usuario` (IN `p_alias` VARCHAR(50), IN `p_contrasena` VARCHAR(255))  READS SQL DATA SQL SECURITY INVOKER BEGIN
    SELECT u.id, u.alias, u.rol_id, r.slug
    FROM usuario u
    INNER JOIN rol r ON r.id = u.rol_id
    WHERE u.alias = p_alias
      AND u.contrasena = p_contrasena
      AND u.estatus = 1
    LIMIT 1;
END$$

DROP PROCEDURE IF EXISTS `sp_verPoliza`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_verPoliza` (IN `p_idUser` INT)  READS SQL DATA BEGIN
    SELECT id, Usuario, Cliente, Poliza, Marca, Modelo, Aseguradora
    FROM vPolizas
    WHERE Usuario = p_idUser;
END$$

