DROP TABLE IF EXISTS `diccionario_datos`;

DROP VIEW IF EXISTS `diccionario_datos`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `diccionario_datos`  AS SELECT `c`.`TABLE_NAME` AS `tabla`, `c`.`ORDINAL_POSITION` AS `orden`, `c`.`COLUMN_NAME` AS `campo`, `c`.`COLUMN_TYPE` AS `tipo_dato`, CASE WHEN `c`.`IS_NULLABLE` = 'YES' THEN 'Si' ELSE 'No' END AS `permite_null`, `c`.`COLUMN_DEFAULT` AS `valor_predeterminado`, CASE WHEN exists(select 1 from `information_schema`.`key_column_usage` `pk` where `pk`.`TABLE_SCHEMA` = `c`.`TABLE_SCHEMA` AND `pk`.`TABLE_NAME` = `c`.`TABLE_NAME` AND `pk`.`COLUMN_NAME` = `c`.`COLUMN_NAME` AND `pk`.`CONSTRAINT_NAME` = 'PRIMARY' limit 1) THEN 'Si' ELSE 'No' END AS `clave_primaria`, coalesce((select group_concat(`uk`.`CONSTRAINT_NAME` separator ', ') from (`information_schema`.`key_column_usage` `uk` join `information_schema`.`table_constraints` `tc` on(`tc`.`CONSTRAINT_SCHEMA` = `uk`.`CONSTRAINT_SCHEMA` and `tc`.`CONSTRAINT_NAME` = `uk`.`CONSTRAINT_NAME` and `tc`.`TABLE_SCHEMA` = `uk`.`TABLE_SCHEMA` and `tc`.`TABLE_NAME` = `uk`.`TABLE_NAME`)) where `uk`.`TABLE_SCHEMA` = `c`.`TABLE_SCHEMA` and `uk`.`TABLE_NAME` = `c`.`TABLE_NAME` and `uk`.`COLUMN_NAME` = `c`.`COLUMN_NAME` and `tc`.`CONSTRAINT_TYPE` = 'UNIQUE'),'') AS `restricciones_unique`, coalesce((select group_concat(concat(`fk`.`CONSTRAINT_NAME`,': ',`fk`.`REFERENCED_TABLE_SCHEMA`,'.',`fk`.`REFERENCED_TABLE_NAME`,'.',`fk`.`REFERENCED_COLUMN_NAME`) separator '; ') from `information_schema`.`key_column_usage` `fk` where `fk`.`TABLE_SCHEMA` = `c`.`TABLE_SCHEMA` and `fk`.`TABLE_NAME` = `c`.`TABLE_NAME` and `fk`.`COLUMN_NAME` = `c`.`COLUMN_NAME` and `fk`.`REFERENCED_TABLE_NAME` is not null),'') AS `referencias_fk`, `c`.`EXTRA` AS `extra`, coalesce(nullif(`c`.`COLUMN_COMMENT`,''),case concat(`c`.`TABLE_NAME`,'.',`c`.`COLUMN_NAME`) when 'rol.id' then 'Identificador del rol.' when 'rol.nombre' then 'Nombre visible del rol.' when 'rol.slug' then 'Identificador del rol utilizado por PHP para comprobar permisos.' when 'usuario.id' then 'Identificador de la cuenta.' when 'usuario.nombre' then 'Nombre de la persona.' when 'usuario.apellido_p' then 'Apellido paterno.' when 'usuario.apellido_m' then 'Apellido materno.' when 'usuario.nacimiento' then 'Fecha de nacimiento.' when 'usuario.genero' then 'Genero declarado por la persona.' when 'usuario.email' then 'Correo electronico de la cuenta.' when 'usuario.contrasena' then 'Valor de la contrasena procesado por la aplicacion; no es el texto de acceso legible.' when 'usuario.alias' then 'Nombre de usuario utilizado para iniciar sesion.' when 'usuario.foto_perfil' then 'Contenido binario de la imagen de perfil.' when 'usuario.estatus' then 'Actividad de la cuenta: PHP permite acceso cuando vale 1. No es el estatus del siniestro.' when 'usuario.rol_id' then 'Rol al que pertenece la cuenta.' when 'aseguradoras.id' then 'Identificador de la compania aseguradora.' when 'aseguradoras.nombre' then 'Nombre de la compania que emite la poliza.' when 'vehiculo.id' then 'Identificador del vehiculo.' when 'vehiculo.marca' then 'Marca del vehiculo.' when 'vehiculo.modelo' then 'Modelo del vehiculo.' when 'vehiculo.color' then 'Color del vehiculo.' when 'vehiculo.placas' then 'Matricula o placas del vehiculo.' when 'vehiculo.num_serie' then 'Numero de serie del vehiculo.' when 'poliza.id' then 'Identificador de la poliza.' when 'poliza.num_poliza' then 'Numero de la poliza emitida por la aseguradora.' when 'poliza.aseguradora_id' then 'Compania emisora de la poliza.' when 'poliza.usuario_id' then 'Cuenta del titular de la poliza.' when 'poliza.vehiculo_id' then 'Vehiculo cubierto por la poliza.' when 'estatus.id' then 'Identificador del estado del siniestro.' when 'estatus.nombre' then 'Nombre del estado en el catalogo de siniestros.' when 'siniestro.id' then 'Identificador o folio del expediente.' when 'siniestro.fecha' then 'Fecha en que ocurrio el siniestro.' when 'siniestro.hora' then 'Hora en que ocurrio el siniestro.' when 'siniestro.direccion' then 'Ubicacion donde ocurrio el siniestro.' when 'siniestro.descripcion' then 'Descripcion de lo ocurrido.' when 'siniestro.fecha_registro' then 'Fecha y hora en que se registro el expediente.' when 'siniestro.ajustador_id' then 'Cuenta del ajustador actualmente asignado al caso.' when 'siniestro.poliza_id' then 'Poliza a la que pertenece el siniestro.' when 'siniestro.estatus_id' then 'Estado actual del expediente.' when 'historialestatus.id' then 'Identificador del cambio de estado.' when 'historialestatus.fecha_actu' then 'Fecha y hora del cambio de estado.' when 'historialestatus.siniestro_id' then 'Siniestro cuyo estado cambio.' when 'historialestatus.estatus_id' then 'Nuevo estado registrado en el historial.' when 'multimedia.id' then 'Identificador de la evidencia.' when 'multimedia.tipo' then 'Clasificacion de la evidencia: fotografia o video.' when 'multimedia.archivo' then 'Contenido binario de la fotografia o del video del expediente.' when 'multimedia.ruta' then 'Ruta conservada para compatibilidad con evidencias antiguas guardadas como archivos.' when 'multimedia.fecha' then 'Fecha y hora en que se cargo la evidencia.' when 'multimedia.siniestro_id' then 'Expediente al que pertenece la evidencia.' when 'evaluacion.id' then 'Identificador de la evaluacion.' when 'evaluacion.diagnostico' then 'Texto del diagnostico del siniestro.' when 'evaluacion.fecha_evaluacion' then 'Fecha y hora de la evaluacion o su ultima actualizacion por PHP.' when 'evaluacion.siniestro_id' then 'Siniestro evaluado.' when 'evaluacion.ajustador_id' then 'Cuenta que guarda el diagnostico; el flujo tambien permite actuar al supervisor.' when 'chat.id' then 'Identificador del mensaje.' when 'chat.mensaje' then 'Texto del mensaje. La aplicacion valida un maximo de 2000 caracteres.' when 'chat.fechamensaje' then 'Fecha y hora en que se envio el mensaje.' when 'chat.siniestro_id' then 'Siniestro cuya conversacion contiene el mensaje.' when 'chat.usuario_id' then 'Cuenta autora del mensaje.' when 'chat.mensaje_padre' then 'Mensaje al que se responde. El envio actual de la aplicacion deja este campo en NULL.' else 'Campo sin descripcion funcional registrada.' end) AS `descripcion` FROM (`information_schema`.`columns` `c` join `information_schema`.`tables` `t` on(`t`.`TABLE_SCHEMA` = `c`.`TABLE_SCHEMA` and `t`.`TABLE_NAME` = `c`.`TABLE_NAME`)) WHERE `c`.`TABLE_SCHEMA` = 'bdm_aseguradora' AND `t`.`TABLE_TYPE` = 'BASE TABLE' ORDER BY `c`.`TABLE_NAME` ASC, `c`.`ORDINAL_POSITION` ASC ;

