--
-- Estructura para la vista `diccionario_relaciones`
--
DROP TABLE IF EXISTS `diccionario_relaciones`;

DROP VIEW IF EXISTS `diccionario_relaciones`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `diccionario_relaciones`  AS SELECT `k`.`TABLE_NAME` AS `tabla`, `k`.`CONSTRAINT_NAME` AS `restriccion_fk`, `k`.`ORDINAL_POSITION` AS `posicion_en_fk`, `k`.`COLUMN_NAME` AS `campo`, `k`.`REFERENCED_TABLE_SCHEMA` AS `base_referenciada`, `k`.`REFERENCED_TABLE_NAME` AS `tabla_referenciada`, `k`.`REFERENCED_COLUMN_NAME` AS `campo_referenciado`, CASE WHEN `c`.`IS_NULLABLE` = 'YES' THEN 'Si' ELSE 'No' END AS `permite_null`, `r`.`UPDATE_RULE` AS `al_actualizar`, `r`.`DELETE_RULE` AS `al_eliminar` FROM (((`information_schema`.`key_column_usage` `k` join `information_schema`.`columns` `c` on(`c`.`TABLE_SCHEMA` = `k`.`TABLE_SCHEMA` and `c`.`TABLE_NAME` = `k`.`TABLE_NAME` and `c`.`COLUMN_NAME` = `k`.`COLUMN_NAME`)) join `information_schema`.`tables` `t` on(`t`.`TABLE_SCHEMA` = `k`.`TABLE_SCHEMA` and `t`.`TABLE_NAME` = `k`.`TABLE_NAME`)) left join `information_schema`.`referential_constraints` `r` on(`r`.`CONSTRAINT_SCHEMA` = `k`.`CONSTRAINT_SCHEMA` and `r`.`CONSTRAINT_NAME` = `k`.`CONSTRAINT_NAME` and `r`.`TABLE_NAME` = `k`.`TABLE_NAME`)) WHERE `k`.`TABLE_SCHEMA` = 'bdm_aseguradora' AND `t`.`TABLE_TYPE` = 'BASE TABLE' AND `k`.`REFERENCED_TABLE_NAME` is not null ORDER BY `k`.`TABLE_NAME` ASC, `k`.`CONSTRAINT_NAME` ASC, `k`.`ORDINAL_POSITION` ASC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `diccionario_tablas`
--
DROP TABLE IF EXISTS `diccionario_tablas`;

DROP VIEW IF EXISTS `diccionario_tablas`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `diccionario_tablas`  AS SELECT `t`.`TABLE_NAME` AS `tabla`, (select count(0) from `information_schema`.`columns` `c` where `c`.`TABLE_SCHEMA` = `t`.`TABLE_SCHEMA` and `c`.`TABLE_NAME` = `t`.`TABLE_NAME`) AS `cantidad_campos`, `t`.`ENGINE` AS `motor`, `t`.`TABLE_COLLATION` AS `cotejamiento`, coalesce(nullif(`t`.`TABLE_COMMENT`,''),case `t`.`TABLE_NAME` when 'rol' then 'Catalogo de roles de las cuentas: asegurado, ajustador y supervisor.' when 'usuario' then 'Cuentas, datos personales, acceso y fotografias de perfil.' when 'aseguradoras' then 'Companias emisoras de las polizas.' when 'vehiculo' then 'Vehiculos cubiertos por las polizas.' when 'poliza' then 'Relacion entre titular, compania aseguradora y vehiculo.' when 'estatus' then 'Catalogo de estados de los siniestros.' when 'siniestro' then 'Expediente principal, poliza, ajustador asignado y estado actual.' when 'historialestatus' then 'Historial de los cambios de estado de cada expediente.' when 'multimedia' then 'Fotografias y videos asociados a cada siniestro.' when 'evaluacion' then 'Diagnostico del siniestro y cuenta que lo registra.' when 'chat' then 'Mensajes agrupados por siniestro; los participantes autorizados los determina PHP.' else 'Tabla sin descripcion funcional registrada.' end) AS `descripcion` FROM `information_schema`.`tables` AS `t` WHERE `t`.`TABLE_SCHEMA` = 'bdm_aseguradora' AND `t`.`TABLE_TYPE` = 'BASE TABLE' ORDER BY `t`.`TABLE_NAME` ASC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vbusquedaavanzada`
--
DROP TABLE IF EXISTS `vbusquedaavanzada`;

DROP VIEW IF EXISTS `vbusquedaavanzada`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vbusquedaavanzada`  AS SELECT `s`.`id` AS `Folio_Siniestro`, `p`.`num_poliza` AS `Numero_Poliza`, concat_ws(' ',`u`.`nombre`,`u`.`apellido_p`) AS `Cliente`, `v`.`marca` AS `Marca`, `v`.`modelo` AS `Modelo`, `v`.`placas` AS `Placas`, `e`.`nombre` AS `Estatus_Actual`, `s`.`fecha` AS `Fecha_Siniestro` FROM ((((`siniestro` `s` join `poliza` `p` on(`s`.`poliza_id` = `p`.`id`)) join `vehiculo` `v` on(`p`.`vehiculo_id` = `v`.`id`)) join `usuario` `u` on(`p`.`usuario_id` = `u`.`id`)) left join `estatus` `e` on(`s`.`estatus_id` = `e`.`id`)) ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vdashboardadmin`
--
DROP TABLE IF EXISTS `vdashboardadmin`;

DROP VIEW IF EXISTS `vdashboardadmin`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vdashboardadmin`  AS SELECT `e`.`nombre` AS `Estatus_Siniestro`, count(`s`.`id`) AS `Cantidad_Total` FROM (`estatus` `e` left join `siniestro` `s` on(`e`.`id` = `s`.`estatus_id`)) GROUP BY `e`.`id`, `e`.`nombre` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vhistorialestatus`
--
DROP TABLE IF EXISTS `vhistorialestatus`;

DROP VIEW IF EXISTS `vhistorialestatus`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vhistorialestatus`  AS SELECT `hs`.`siniestro_id` AS `siniestro_id`, `e`.`nombre` AS `Estatus_Nuevo`, `hs`.`fecha_actu` AS `Fecha_Cambio` FROM (`historialestatus` `hs` join `estatus` `e` on(`hs`.`estatus_id` = `e`.`id`)) ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vlistarajustadores`
--
DROP TABLE IF EXISTS `vlistarajustadores`;

DROP VIEW IF EXISTS `vlistarajustadores`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vlistarajustadores`  AS SELECT `u`.`id` AS `Ajustador_ID`, concat_ws(' ',`u`.`nombre`,`u`.`apellido_p`) AS `Nombre_Ajustador`, count(`s`.`id`) AS `Siniestros_Asignados` FROM ((`usuario` `u` join `rol` `r` on(`u`.`rol_id` = `r`.`id`)) left join `siniestro` `s` on(`u`.`id` = `s`.`ajustador_id`)) WHERE `r`.`slug` = 'ajustador' GROUP BY `u`.`id`, `u`.`nombre`, `u`.`apellido_p` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vlistarclientes`
--
DROP TABLE IF EXISTS `vlistarclientes`;

DROP VIEW IF EXISTS `vlistarclientes`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vlistarclientes`  AS SELECT `u`.`id` AS `Cliente_ID`, concat_ws(' ',`u`.`nombre`,`u`.`apellido_p`,nullif(`u`.`apellido_m`,'')) AS `Nombre_Completo`, `u`.`email` AS `email`, count(distinct `p`.`id`) AS `Total_Polizas`, count(distinct `s`.`id`) AS `Total_Siniestros` FROM (((`usuario` `u` join `rol` `r` on(`u`.`rol_id` = `r`.`id`)) left join `poliza` `p` on(`u`.`id` = `p`.`usuario_id`)) left join `siniestro` `s` on(`p`.`id` = `s`.`poliza_id`)) WHERE `r`.`slug` = 'asegurado' GROUP BY `u`.`id`, `u`.`nombre`, `u`.`apellido_p`, `u`.`apellido_m`, `u`.`email` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vlistarsiniestros`
--
DROP TABLE IF EXISTS `vlistarsiniestros`;

DROP VIEW IF EXISTS `vlistarsiniestros`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vlistarsiniestros`  AS SELECT `s`.`id` AS `id`, `s`.`fecha` AS `fecha`, `s`.`hora` AS `hora`, `s`.`direccion` AS `direccion`, `s`.`descripcion` AS `descripcion`, `s`.`ajustador_id` AS `ajustador_id`, `vp`.`Poliza` AS `Poliza`, `vp`.`Usuario` AS `Usuario`, `vp`.`Cliente` AS `nombreCliente`, `vp`.`Marca` AS `Marca`, `vp`.`Modelo` AS `Modelo`, `vp`.`Aseguradora` AS `Aseguradora`, ifnull(`e`.`nombre`,'Sin Estatus') AS `Estatus`, ifnull(`u_ajustador`.`nombre`,'No Asignado') AS `Ajustador` FROM (((`siniestro` `s` join `vpolizas` `vp` on(`s`.`poliza_id` = `vp`.`id`)) left join `estatus` `e` on(`s`.`estatus_id` = `e`.`id`)) left join `usuario` `u_ajustador` on(`s`.`ajustador_id` = `u_ajustador`.`id`)) ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vlogin`
--
DROP TABLE IF EXISTS `vlogin`;

DROP VIEW IF EXISTS `vlogin`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vlogin`  AS SELECT `u`.`id` AS `id`, `u`.`alias` AS `alias`, `u`.`contrasena` AS `contrasena`, `u`.`rol_id` AS `rol_id`, `r`.`nombre` AS `NombreRol`, `r`.`slug` AS `slug` FROM (`usuario` `u` join `rol` `r` on(`u`.`rol_id` = `r`.`id`)) ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vpolizas`
--
DROP TABLE IF EXISTS `vpolizas`;

DROP VIEW IF EXISTS `vpolizas`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vpolizas`  AS SELECT `p`.`id` AS `id`, `p`.`usuario_id` AS `Usuario`, `u`.`nombre` AS `Cliente`, `p`.`num_poliza` AS `Poliza`, `v`.`marca` AS `Marca`, `v`.`modelo` AS `Modelo`, `a`.`nombre` AS `Aseguradora` FROM (((`poliza` `p` join `vehiculo` `v` on(`p`.`vehiculo_id` = `v`.`id`)) join `aseguradoras` `a` on(`p`.`aseguradora_id` = `a`.`id`)) join `usuario` `u` on(`p`.`usuario_id` = `u`.`id`)) ;

